int count=0;
void check(bool b,const char*s){if(!b)throw std::runtime_error(s);count++;}
void rejects(std::function<void()>f,const char*s){bool fail=false;try{f();}catch(const std::exception&){fail=true;}check(fail,s);}
QByteArray bytes(QString p){QFile f(p);need(f.open(QIODevice::ReadOnly),"test read");return f.readAll();}
QString sql(QString path,QString statement){QString n=QUuid::createUuid().toString(),out;{auto db=QSqlDatabase::addDatabase("QSQLITE",n);db.setDatabaseName(path);need(db.open(),"test sqlite");{QSqlQuery q(db);need(q.exec(statement),"test sql");if(q.next())out=q.value(0).toString();}db.close();}QSqlDatabase::removeDatabase(n);return out;}
bool historyExists(QString path){return sql(path,"SELECT count(*) FROM sqlite_master WHERE name='watchlist_reconciliation_history'")=="1";}
QJsonObject group(QString id,QJsonArray members,bool ro=false){QJsonObject g{{"groupId",id},{"name","同名组"},{"color","#334455"},{"readOnly",ro},{"memberIds",members},{"sourceMeta",QJsonObject{{"original","配置证据📚"},{"number",1.25}}}};if(ro)g["sourceId"]="synthetic-imported-read-only";return g;}
QJsonObject input(){QJsonArray roster;for(QString id:{"SH:stock:600000","SH:etf:600000","SZ:stock:600000"}){auto p=id.split(':');roster.append(QJsonObject{{"id",id},{"name","合成标的"},{"symbol",p[0].toLower()+p[2]},{"quote",QJsonObject{{"price",0},{"marker","QUOTE_ONLY_INJECTED"}}}});}return {{"instruments",roster},{"mainIds",QJsonArray{"SH:stock:600000","SH:etf:600000","SZ:stock:600000"}},{"legacyGroups",QJsonArray{group("local:a",{"SH:stock:600000","SH:etf:600000"}),group("imported:42",{"SH:etf:600000","SZ:stock:600000"},true),group("local:empty",{})}}};}
QJsonObject changed(QJsonObject in){QJsonArray roster;for(auto v:in.value("instruments").toArray())if(v.toObject().value("id")!="SH:etf:600000")roster.append(v);roster.append(QJsonObject{{"id","BJ:stock:830001"},{"name","合成新增证券"},{"quote",QJsonObject{{"price",0},{"marker","QUOTE_ONLY_INJECTED"}}}});in["instruments"]=roster;in["mainIds"]=QJsonArray{"SZ:stock:600000","BJ:stock:830001","SH:stock:600000"};return in;}
void click(WatchlistReconciliationPage&p,const char*id){auto*b=p.findChild<QPushButton*>(id);check(b!=nullptr,"native control exists");b->click();QApplication::processEvents();}
